import{z as B,x as n,o as E,c as A,q as o,j as l,D as e,d as r,s as i,S as d}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"仓库级代码排布","description":"","frontmatter":{"title":"仓库级代码排布","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/repo-level-code-data.md","filePath":"llm/repo-level-code-data.md","lastUpdated":1791063341000}'),s={name:"llm/repo-level-code-data.md"};function p(c,a,h,m,_,u){const t=n("Mermaid");return E(),A("div",null,[a[2]||(a[2]=o('<h1 id="仓库级代码排布" tabindex="-1">仓库级代码排布 <a class="header-anchor" href="#仓库级代码排布" aria-label="Permalink to &quot;仓库级代码排布&quot;">​</a></h1><div class="epigraph"><p>源文件不是独立网页：import、测试与配置隔着路径互相指认。把仓库打散按文件随机洗牌，模型就学不到一次改动该同时看见的那些邻居。</p><footer>—— 据 Li 等 StarCoder、Rozière 等 Code Llama 对仓库级上下文的处理整理</footer></div><p><a href="/llm/multilingual-alpha-sampling">上一课</a>用 \\(p^\\alpha\\) 给自然语言语种加权重。代码的「语种」是 Python 与 Java，但依赖图活在仓库里，不活在语言识别标签里。本课不重讲 α。缺口是：代码桶内部如何排布，才能让同一仓库的文件在上下文中共同出现，而不是被全局 shuffle 拆成互不认识的碎片。后课 FIM 改训练目标；本课先改数据的空间邻近。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>网页可以近似 i.i.d. 文档。Git 仓库不行：<code>foo.py</code> 的符号在 <code>test_foo.py</code> 与 <code>utils.py</code> 里被引用。按文件随机采样，窗口里几乎看不到定义与调用同屏。<span class="marginnote">直觉类比：一个仓库像一部长篇小说，函数定义在第 3 章、调用在第 17 章，人物只在连续的章节里才立得起来。按文件洗牌等于把所有书撕成单页混进一个纸箱再随机抽五页——抽到「他拔出剑」时，你既不知道他是谁，也不知道剑从哪来。仓库级排布则是按原书顺序把连续几章打包成一叠。</span>StarCoder 一类语料强调 The Stack 的仓库结构；Code Llama、DeepSeek-Coder 的报告里也把仓库级上下文当成代码能力的来源之一。配比里写「15% 代码」若只是把文件当网页喂，fertility 还在，依赖却没了。</p><p>去重也要改单位。文件级 MinHash 会删掉大量合法的相似工具函数；仓库级去重（近重复项目、fork）才能去掉模板生成的整库拷贝，而不误杀同组织下的近邻文件。这与 <a href="/llm/web-clean-dedup">网页去重</a> 同族，分辨率不同。</p><h3 id="许可证与生成文件" tabindex="-1">许可证与生成文件 <a class="header-anchor" href="#许可证与生成文件" aria-label="Permalink to &quot;许可证与生成文件&quot;">​</a></h3><p>仓库级采样会把 <code>LICENSE</code>、<code>node_modules</code>、锁文件、小数据样例一并带进窗口。必须在仓库内再过滤路径，否则 α 式「多喂代码」喂的是许可证全文。生成代码（protobuf、前端 build）会主导频率，污染词表与模型。</p><p><span class="marginnote">同一仓库超长时不能整库塞进上下文。排布的目标是提高「相关文件同批出现」的概率，不是承诺无限仓库注意力。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>以仓库为抽样原子：先按仓库加权（星标、语言、去重后体积），再在仓库内按拓扑或启发式排文件——依赖图近邻、同目录、测试与实现成对、README 与源文件相邻。把排好的文件拼接成超文档，再按上下文窗口切段，段与段之间尽量不把一对定义/引用切开。<span class="marginnote">数字实例：设某仓库有 200 个文件，一个 8k token 的窗口大约装得下 5 个源文件。若全局按文件均匀洗牌，窗口恰好同时抽到某个函数的定义与它的调用方的概率只有约 \\(5/200 \\times 4/199\\) 这个量级——不到千分之一；仓库级打包则让每一窗都是同库邻居，依赖边几乎必进上下文。</span>无法建图时，退化为「同仓库文件连续打包，目录字典序」，仍优于全局文件洗牌。</p>',11)),(E(),l(d,null,{default:e(()=>[i(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20SHUF%5B%22%E5%85%A8%E5%B1%80%E6%96%87%E4%BB%B6%E6%B4%97%E7%89%8C%22%5D%0A%20%20%20%20direction%20LR%0A%20%20%20%20A1%5B%22%E4%BB%93%E5%BA%93A%E6%96%87%E4%BB%B6%22%5D%20--%3E%20M1%5B%22%E6%89%93%E6%95%A3%E8%BF%9B%E6%96%87%E4%BB%B6%E6%B1%A0%22%5D%0A%20%20%20%20B1%5B%22%E4%BB%93%E5%BA%93B%E6%96%87%E4%BB%B6%22%5D%20--%3E%20M1%0A%20%20%20%20M1%20--%3E%20W1%5B%22%E7%AA%97%E5%8F%A3%3A%20%E4%BA%94%E9%A1%B5%E6%9D%A5%E8%87%AA%E4%BA%94%E6%9C%AC%E4%B9%A6%22%5D%0A%20%20end%0A%20%20subgraph%20PKG%5B%22%E4%BB%93%E5%BA%93%E7%BA%A7%E6%89%93%E5%8C%85%22%5D%0A%20%20%20%20direction%20LR%0A%20%20%20%20A2%5B%22%E4%BB%93%E5%BA%93A%E6%8C%89%E4%BE%9D%E8%B5%96%E5%BA%8F%22%5D%20--%3E%20P1%5B%22%E6%8B%BC%E6%88%90%E8%B6%85%E6%96%87%E6%A1%A3%E5%88%87%E6%AE%B5%22%5D%0A%20%20%20%20P1%20--%3E%20W2%5B%22%E7%AA%97%E5%8F%A3%3A%20%E5%AE%9A%E4%B9%89%E4%B8%8E%E8%B0%83%E7%94%A8%E5%90%8C%E5%B1%8F%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p>与领域 \\(w\\) 的接口：代码桶的 token 份额由配比决定；桶内概率质量按仓库分配，而不是按文件均匀。小仓库过采样会让玩具项目占满，应设体积下限与上限。StarCoder 对许可证与近重复仓库的过滤，应发生在加权之前。</p><h3 id="与词表的关系" tabindex="-1">与词表的关系 <a class="header-anchor" href="#与词表的关系" aria-label="Permalink to &quot;与词表的关系&quot;">​</a></h3><p>仓库级文本会改变标识符共现，但不改变已经冻结的切分。若词表几乎没见过该语言的 API，FIM 与仓库排布只能让模型在碎片上拼名字。词表语料里要有代码分层，本课不再重训 \\(V\\)。</p><p><span class="marginnote">多语言仓库（文档英语、代码俄语注释）不要拆成两个 α 桶再拼回来，否则 README 与源文件永远不同屏。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>语言模型的条件分布在窗口内是全连接的。把互相指认的文件放进同一窗口，等于把依赖边变成注意力可以打分的位置对；洗牌则把这些边赶到跨窗口，只能靠参数记忆，而参数记不住每个仓库。这是数据布局对架构的补偿，不是新的注意力公式。<span class="marginnote">常见误区：把仓库级排布理解成「训练后模型能随时翻看整个仓库」。推理时模型仍然只有当前对话窗口，排布改变的只是权重里学到的先验——它见过足够多「定义与调用同屏」的样本，于是更会写一致的接口、更会补测试。想要真在推理时检索别的文件，那是 RAG 或工具调用要解决的问题。</span></p>',6)),(E(),l(d,null,{default:e(()=>[i(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20REPO%5B%22%E5%8E%BB%E9%87%8D%E5%90%8E%E7%9A%84%E4%BB%93%E5%BA%93%22%5D%20--%3E%20FILT%5B%22%E8%B7%AF%E5%BE%84%E4%B8%8E%E8%AE%B8%E5%8F%AF%E8%AF%81%E8%BF%87%E6%BB%A4%22%5D%0A%20%20FILT%20--%3E%20ORD%5B%22%E8%BF%91%E9%82%BB%20%2F%20%E7%9B%AE%E5%BD%95%E5%BA%8F%E6%8E%92%E5%B8%83%22%5D%0A%20%20ORD%20--%3E%20PACK%5B%22%E6%8B%BC%E6%88%90%E8%B6%85%E6%96%87%E6%A1%A3%E5%86%8D%E5%88%87%E7%AA%97%22%5D%0A%20%20W%5B%22%E4%BB%A3%E7%A0%81%E6%A1%B6%E6%9D%83%E9%87%8D%20w%22%5D%20--%3E%20REPO%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>排布不提供填空式的双向条件——那是 FIM。也不解决超长单文件；长文档上采样课会处理「要不要更频繁地见到长序列」。仓库级还放大隐私与密钥泄漏面，扫描应在打包前做完。下一课在已经邻近的代码序列上改目标：故意挖中间，让模型学会在左右上下文之间填。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲语种 α；代码桶的原子是仓库不是文件。</li><li>同库近邻打包，让定义与引用进入同一窗口。</li><li>去重、许可证、生成目录在加权前处理。</li><li>排布补偿的是数据布局，不是无限上下文。</li><li>出处：Li et al., StarCoder, 2023；Rozière et al., Code Llama, 2023；Kocetkov et al., The Stack。</li></ul>',4))])}const C=B(s,[["render",p]]);export{D as __pageData,C as default};
